 drivers/usb/typec/ucsi/Kconfig      |  10 +
 drivers/usb/typec/ucsi/Makefile     |   1 +
 drivers/usb/typec/ucsi/ucsi_itepd.c | 354 ++++++++++++++++++++++++++++++++++++
 4 files changed, 366 insertions(+)

