+void target_stat_count_sent_status(struct se_lun *lun, u8 scsi_status,
+				 u32 flags)
+{
+	if (flags & SCF_SCSI_TMR_CDB)
+		return;
+
+	switch (scsi_status) {
+	case SAM_STAT_BUSY:
+		if (lun && lun->lun_stats)
+			this_cpu_inc(lun->lun_stats->busy_statuses);
+		break;
+	default:
+		break;
+	}
+}
